        "speechText": "Art. 8º É livre a associação profissional ou sindical: a lei não poderá exigir autorização do Estado para a fundação de sindicato; é vedada a criação de mais de uma organização sindical na mesma base territorial (unicidade sindical); é obrigatória a participação dos sindicatos nas negociações coletivas de trabalho."
